async function ensureOfficialPdfFont(size="16pt") {
  if (!document.fonts) return true;
  await document.fonts.ready;
  await Promise.allSettled([
    document.fonts.load(`${size} "${OFFICIAL_PDF_FONT}"`),
    document.fonts.load(`${size} "${OFFICIAL_PDF_FONT_ALIAS}"`)
  ]);
  return document.fonts.check(`${size} "${OFFICIAL_PDF_FONT}"`) || document.fonts.check(`${size} "${OFFICIAL_PDF_FONT_ALIAS}"`);
}

