function confirmPasswordForSignatureSettings(){
  return new Promise(resolve=>{
    const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>ยืนยันรหัสผ่าน</h3><p>ยืนยันตัวตนก่อนเปิดการลงนาม/อนุมัติอัตโนมัติ</p></div><button class="modal-close">×</button></div><div class="field"><label>รหัสผ่านปัจจุบัน</label><input class="input" id="signature-confirm-password" type="password" autocomplete="current-password"></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="signature-confirm-submit">ยืนยัน</button></div></div>`;document.body.appendChild(m);
    const done=v=>{m.remove();resolve(v)};m.querySelector('.modal-close').onclick=()=>done(null);m.querySelector('.modal-cancel').onclick=()=>done(null);m.querySelector('#signature-confirm-submit').onclick=()=>done(m.querySelector('#signature-confirm-password').value||null);m.querySelector('#signature-confirm-password').focus();
  });
}
async function saveMySignatureSettings(button){
  const method=document.querySelector('input[name="my-signature-method"]:checked')?.value||'saved';
  const defaultId=method==='paper'?null:(document.querySelector('#my-signature-default')?.value||null);
  const autoSign=method==='saved'&&!!document.querySelector('#my-auto-sign')?.checked;
  const autoApprove=autoSign&&!!document.querySelector('#my-auto-approve')?.checked;
  if(method==='saved'&&!defaultId)return toast('กรุณาเลือกลายเซ็นหลัก','หรือเลือก “เซ็นบนกระดาษ”','error');
  const attempt=async()=>supabase.rpc('set_my_signature_preferences',{p_preferred_method:method,p_default_signature_id:defaultId,p_auto_sign_enabled:autoSign,p_auto_approve_enabled:autoApprove});
  buttonLoading(button,true,'กำลังบันทึก...');let res=await attempt();
  if(res.error&&/ยืนยันรหัสผ่าน/.test(res.error.message||'')){
    buttonLoading(button,false);const password=await confirmPasswordForSignatureSettings();if(!password)return;
    const authRes=await supabase.auth.signInWithPassword({email:state.user.email,password});if(authRes.error)return toast('ยืนยันรหัสผ่านไม่สำเร็จ',authRes.error.message,'error');
    buttonLoading(button,true,'กำลังบันทึก...');res=await attempt();
  }
  buttonLoading(button,false);if(res.error)return toast('บันทึกการตั้งค่าไม่สำเร็จ',res.error.message,'error');
  await refreshMySignatureProfile();
  if(state.signaturePreferences?.auto_sign_enabled){const autoRes=await supabase.rpc('run_my_academic_auto_actions');state.signatureAutomationLast=autoRes.error?null:autoRes.data;}
  toast('บันทึกการตั้งค่าลายเซ็นแล้ว',autoSign?'Auto Sign พร้อมใช้งานในระบบที่รองรับ':'อัปเดตวิธีลงนามเรียบร้อย','success');await renderDashboard();
}
function bindSignatureSettingsEvents(){
  document.querySelectorAll('input[name="my-signature-method"]').forEach(x=>x.addEventListener('change',()=>{const paper=document.querySelector('input[name="my-signature-method"]:checked')?.value==='paper';const sel=document.querySelector('#my-signature-default'),sg=document.querySelector('#my-auto-sign'),ap=document.querySelector('#my-auto-approve');if(sel)sel.disabled=paper;if(sg)sg.disabled=paper||!state.signatures.length;if(ap)ap.disabled=paper||!state.signatures.length||!state.signaturePreferences?.can_enable_auto_approve;if(paper){if(sg)sg.checked=false;if(ap)ap.checked=false;}}));
  document.querySelector('#my-signature-draw')?.addEventListener('click',()=>signatureManagerModal('drawn'));
  document.querySelector('#my-signature-upload')?.addEventListener('click',()=>signatureManagerModal('upload'));
  document.querySelector('#my-signature-manage')?.addEventListener('click',()=>signatureManagerModal());
  document.querySelector('#my-signature-settings-save')?.addEventListener('click',e=>saveMySignatureSettings(e.currentTarget));
  document.querySelectorAll('[data-signature-settings-preview]').forEach(b=>b.addEventListener('click',()=>previewSignature(b.dataset.signatureSettingsPreview)));
  document.querySelector('#my-auto-sign')?.addEventListener('change',e=>{if(!e.currentTarget.checked){const a=document.querySelector('#my-auto-approve');if(a)a.checked=false;}});
  document.querySelector('#my-auto-approve')?.addEventListener('change',e=>{if(e.currentTarget.checked){const s=document.querySelector('#my-auto-sign');if(s)s.checked=true;}});
}

