async function academicCalendarExport(kind){const calendar=academicCalendarCurrent();if(!calendar)return;const source=document.querySelector("#academic-calendar-export-document");if(!source)return;const btn=document.querySelector(kind==="pdf"?"#academic-calendar-export-pdf":"#academic-calendar-export-image");buttonLoading(btn,true,"กำลังสร้างไฟล์...");try{await ensureOfficialPdfFont("16px");const canvas=await html2canvas(source,{scale:2.2,backgroundColor:"#ffffff",useCORS:true,logging:false});const fileBase=`BNK_ปฏิทิน100วัน_${calendar.academic_year}_ภาคเรียน${calendar.semester}`;if(kind==="image"){canvas.toBlob(blob=>{if(blob)downloadBlob(blob,`${fileBase}.png`);},"image/png",1);}else{const pdf=new jsPDF({orientation:"landscape",unit:"mm",format:"a4"}),pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),margin=5,ratio=Math.min((pw-margin*2)/canvas.width,(ph-margin*2)/canvas.height),w=canvas.width*ratio,h=canvas.height*ratio,x=(pw-w)/2,y=(ph-h)/2;pdf.addImage(canvas.toDataURL("image/jpeg",0.96),"JPEG",x,y,w,h);pdf.save(`${fileBase}.pdf`);}toast("สร้างไฟล์เรียบร้อย",kind==="pdf"?"ดาวน์โหลด PDF แล้ว":"ดาวน์โหลดรูปภาพ PNG แล้ว","success");}catch(err){console.error(err);toast("Export ไม่สำเร็จ",err?.message||"เกิดข้อผิดพลาด","error");}finally{buttonLoading(btn,false);}}



const ACADEMIC_REGISTRATION_SECTION_LABEL = {
  home:"เลือกระบบย่อยงานทะเบียน",
  transfer:"คำร้องใบย้ายนักเรียน",
  certificate:"คำร้องใบรับรองนักเรียน",
  document_service:"ร้องขอรับบริการเอกสารทางการศึกษา",
  // Legacy routes retained only for backward compatibility.
  qualification:"ร้องขอรับบริการเอกสารทางการศึกษา",
  verification:"ร้องขอรับบริการเอกสารทางการศึกษา",
};
const ACADEMIC_TRANSFER_STATUS_LABEL = {draft:"แบบร่าง",submitted:"ยื่นคำร้องแล้ว",approved:"อนุมัติ",rejected:"ไม่อนุมัติ"};
const ACADEMIC_CERTIFICATE_STATUS_LABEL = ACADEMIC_TRANSFER_STATUS_LABEL;
const ACADEMIC_CERTIFICATE_PURPOSE_LABEL = {
  passport_area:"ใช้เป็นหลักฐานประกอบการขอหนังสือเดินทางออกนอกพื้นที่",
  civil_registration:"ใช้เป็นหลักฐานประกอบการพิจารณาจัดทำทะเบียนประวัติบุคคล",
  id_card:"ใช้เป็นหลักฐานประกอบการทำบัตรประจำตัวประชาชน",
  other:"อื่น ๆ"
};

function academicRegistrationCanManageUi(){
  const s=state.academicRegistrationSettings||{};
  return state.profile?.role==="super_admin"||s.registrar_user_id===state.user?.id;
}
function academicRegistrationCanConfigureUi(){return academicRegistrationCanManageUi()||isAcademicHead();}
function academicRegistrationCanFinalizeUi(){
  const s=state.academicRegistrationSettings||{};
  return state.profile?.role==="super_admin"||isAcademicHead()||s.registrar_user_id===state.user?.id;
}
function academicTransferFilesFor(requestId){return (state.academicTransferFiles||[]).filter(f=>f.request_id===requestId).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0)||String(a.created_at||"").localeCompare(String(b.created_at||"")));}
function academicTransferSignaturesFor(requestId){return (state.academicTransferSignatures||[]).filter(s=>s.request_id===requestId);}
function academicTransferSignatureFor(requestId,slot){return academicTransferSignaturesFor(requestId).find(s=>s.signer_slot===slot)||null;}
function academicTransferCanEditUi(r){return !!r&&(academicRegistrationCanManageUi()||(r.created_by===state.user?.id&&r.status==="draft"));}
function approvalRegistrationDecision(systemCode,r,slot){
  if(!r)return "pending";
  if(systemCode==="academic_transfer")return slot==="finance"?(r.finance_decision||"pending"):slot==="registrar"?(r.registrar_decision||"pending"):slot==="assessment"?(r.assessment_decision||"pending"):(r.director_decision||"pending");
  if(systemCode==="academic_certificate")return slot==="preparer"?(r.preparer_decision||"pending"):slot==="registrar"?(r.registrar_decision||"pending"):(r.director_decision||"pending");
  if(systemCode==="academic_document_service")return slot==="assessment"?(r.assessment_decision||"pending"):slot==="registrar"?(r.registrar_decision||"pending"):(r.director_decision||"pending");
  return "pending";
}
function approvalRegistrationSlotAvailableUi(systemCode,r,slot){
  if(!r||approvalIsParallel(systemCode))return true;
  const order=approvalSystemConfig(systemCode)?.slot_order||[];
  const idx=order.indexOf(slot);
  if(idx<=0)return true;
  return order.slice(0,idx).every(prev=>["approve","skipped"].includes(approvalRegistrationDecision(systemCode,r,prev)));
}
function academicTransferCanReviewSlotUi(slot,r=null){
  let roleAllowed=false;
  if(state.profile?.role==="super_admin")roleAllowed=true;
  else{
    const s=state.academicRegistrationSettings||{};
    if(slot==="finance")roleAllowed=s.finance_user_id===state.user?.id;
    else if(slot==="registrar")roleAllowed=s.registrar_user_id===state.user?.id;
    else if(slot==="assessment")roleAllowed=s.assessment_user_id===state.user?.id;
    else if(slot==="director")roleAllowed=isCurrentDirectorExecutive()||s.director_user_id===state.user?.id;
  }
  return roleAllowed&&(!r||approvalRegistrationSlotAvailableUi("academic_transfer",r,slot));
}
function academicTransferSignatureMethodLabel(method){return method==="paper"?"เซ็นสดบนกระดาษ":method==="drawn"?"เซ็นสดในระบบ":method==="upload"?"อัปโหลดรูปลายเซ็น":"ยังไม่กำหนด";}
function academicTransferSlotLabel(slot){return slot==="finance"?"ครูการเงิน / เจ้าหน้าที่การเงิน":slot==="registrar"?"ครูทะเบียน":slot==="assessment"?"ครูวัดและประเมินผล":"ผู้บริหารสถานศึกษา";}
function academicTransferStudentName(s){
  const prefix=String(s?.prefix||"").trim(),first=String(s?.first_name||"").trim(),last=String(s?.last_name||"").trim();
  return `${prefix}${first}${last?` ${last}`:""}`.trim();
}
function academicTransferStudentOptionLabel(s){return `เลขที่ ${s.student_number||"—"} · ${academicTransferStudentName(s)} · รหัส ${s.student_code||"—"}`;}
function academicTransferClassOptions(students){
  const seen=new Set(),rows=[];
  (students||[]).forEach(s=>{if(s.class_id&&!seen.has(s.class_id)){seen.add(s.class_id);rows.push({id:s.class_id,label:s.class_label||"—"});}});
  return rows;
}
