function academicCertificateRequestRunningNumber(r){
  const code=String(r?.request_code||"").trim();
  const m=code.match(/^CER-(\d{4})-(\d+)$/i);
  if(m){
    const year=m[1];
    const serial=String(Number(m[2])||1);
    return `${academicRegThaiDigits(serial)}/${academicRegThaiDigits(year)}`;
  }
  const year=String(r?.academic_year||state.academicRegistrationAcademicYear||currentAcademicPeriod().academicYear||"2569");
  return `๑/${academicRegThaiDigits(year)}`;
}
