async function lessonUsageSignatureBlob(modal,work,method,fileId){if(method==="paper")return {blob:null,mime:null};if(method==="drawn"){if(!modal._signatureHasInk?.())throw new Error("กรุณาเซ็นในกรอบก่อนดำเนินการ");return {blob:await canvasBlob(work.querySelector("#signature-canvas")),mime:"image/png"};}const f=work.querySelector(`#${fileId}`)?.files?.[0];if(!f)throw new Error("กรุณาเลือกรูปลายเซ็น");if(!["image/png","image/jpeg","image/webp"].includes(f.type))throw new Error("รองรับเฉพาะ PNG / JPG / WebP");return {blob:f,mime:f.type};}
