function officialAttendanceStopMedia(stream){try{stream?.getTracks?.().forEach(t=>t.stop());}catch{}}
function officialAttendanceTestDistanceMeters(lat1,lng1,lat2,lng2){const toRad=v=>Number(v)*Math.PI/180,R=6371000,dLat=toRad(Number(lat2)-Number(lat1)),dLng=toRad(Number(lng2)-Number(lng1)),a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2;return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
async function officialAttendanceTestGps(statusEl=null){const s=state.officialAttendanceSettings||{};if(s.school_latitude==null||s.school_longitude==null)throw new Error("ยังไม่ได้ตั้งค่าพิกัดโรงเรียน");if(statusEl)statusEl.textContent="กำลังอ่านตำแหน่ง GPS…";const c=await officialAttendanceGetPrecisePosition(),distance=officialAttendanceTestDistanceMeters(c.latitude,c.longitude,Number(s.school_latitude),Number(s.school_longitude)),radius=Number(s.allowed_radius_m||250),accuracyLimit=Number(s.max_accuracy_m||150),accuracy=Number(c.accuracy||0),inside=distance<=radius,accurate=!accuracy||accuracy<=accuracyLimit;if(!accurate)throw new Error(`GPS คลาดเคลื่อน ±${Math.round(accuracy)} เมตร เกินค่าที่กำหนด ${accuracyLimit} เมตร`);if(!inside)throw new Error(`GPS อยู่นอกพื้นที่โรงเรียนประมาณ ${Math.round(distance)} เมตร (กำหนดไม่เกิน ${radius} เมตร)`);if(statusEl)statusEl.innerHTML=`<strong>GPS ผ่าน ✓</strong><span>ห่างจุดโรงเรียน ${Math.round(distance)} เมตร · ความแม่นยำ ±${Math.round(accuracy)} เมตร</span>`;return {latitude:c.latitude,longitude:c.longitude,accuracy,distance,radius};}
function officialAttendanceTestToken(){try{return crypto.randomUUID();}catch{return `${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`;}}
function officialAttendanceTestQrPayload(){return `BNKATTTEST|1|${officialAttendanceDateValue()}|${officialAttendanceTestToken()}`;}
function officialAttendanceParseTestQr(text){const p=String(text||"").trim().split("|");return p.length===4&&p[0]==="BNKATTTEST"&&p[1]==="1"?{date:p[2],token:p[3]}:null;}
