function officialAttendanceFaceManagerModal(){if(!officialAttendanceCanManageUi())return;const statuses=new Map((state.officialAttendanceFaceStatuses||[]).map(x=>[x.user_id,x])),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal modal-wide"><div class="modal-head"><div><h3>จัดการการลงทะเบียนใบหน้า</h3><p>ผู้ดูแลเห็นเฉพาะสถานะการลงทะเบียน ไม่สามารถดู Face Template ของบุคลากร</p></div><button class="modal-close">×</button></div><div class="table-wrap"><table class="table"><thead><tr><th>ชื่อ–นามสกุล</th><th>ตำแหน่ง</th><th>สถานะ</th><th>ลงทะเบียนเมื่อ</th><th></th></tr></thead><tbody>${(state.officialAttendanceRoster||[]).filter(p=>p.role!=="super_admin").map(p=>{const st=statuses.get(p.id);return `<tr><td><strong>${escapeHtml(p.full_name||p.email||"-")}</strong></td><td>${escapeHtml(officialAttendanceRosterPosition(p.id))}</td><td><span class="attendance-status ${st?.registered?"on_time":"pending_checkin"}">${st?.registered?"ลงทะเบียนแล้ว":"ยังไม่ลงทะเบียน"}</span></td><td>${st?.registered_at?escapeHtml(new Intl.DateTimeFormat("th-TH",{dateStyle:"medium",timeStyle:"short",timeZone:"Asia/Bangkok"}).format(new Date(st.registered_at))):"—"}</td><td>${st?.registered?`<button class="btn btn-danger btn-sm" data-attendance-face-reset="${p.id}">รีเซ็ตใบหน้า</button>`:""}</td></tr>`;}).join("")}</tbody></table></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelectorAll("[data-attendance-face-reset]").forEach(b=>b.onclick=async()=>{const p=(state.officialAttendanceRoster||[]).find(x=>x.id===b.dataset.attendanceFaceReset);if(!window.confirm(`รีเซ็ตข้อมูลใบหน้าของ ${p?.full_name||"บุคลากรรายนี้"} หรือไม่?`))return;buttonLoading(b,true,"กำลังรีเซ็ต...");const {error}=await supabase.rpc("admin_reset_official_attendance_face",{p_user_id:b.dataset.attendanceFaceReset});if(error){buttonLoading(b,false);return toast("รีเซ็ตไม่สำเร็จ",error.message,"error");}toast("รีเซ็ตข้อมูลใบหน้าแล้ว","บุคลากรต้องลงทะเบียนใบหน้าใหม่ก่อนใช้งาน","success");close();await loadOfficialAttendanceWorkspace();await renderDashboard();});}
async function officialAttendanceDeleteFaceRegistration(button){if(!state.officialAttendanceFaceStatus?.registered)return;if(!window.confirm("ลบข้อมูลใบหน้าที่ลงทะเบียนไว้หรือไม่? หลังลบจะใช้โหมด Face Verification ไม่ได้จนกว่าจะลงทะเบียนใหม่"))return;buttonLoading(button,true,"กำลังลบ...");try{const {error}=await supabase.rpc("delete_my_official_attendance_face");if(error)throw error;toast("ลบข้อมูลใบหน้าแล้ว","สามารถลงทะเบียนใหม่ได้ทุกเมื่อ","success");await loadOfficialAttendanceWorkspace();await renderDashboard();}catch(err){toast("ลบข้อมูลไม่สำเร็จ",err.message||String(err),"error");}finally{buttonLoading(button,false);}}
function officialAttendanceSettingsModal(){
  if(!officialAttendanceCanManageUi())return;const s=state.officialAttendanceSettings||{},mode=s.attendance_mode||"gps",rootAdmin=isSuperAdminUser(),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal modal-wide"><div class="modal-head"><div><h3>ตั้งค่าระบบลงเวลาปฏิบัติราชการ</h3><p>กำหนดรูปแบบการลงเวลา พิกัดโรงเรียน รัศมี และช่วงเวลา</p></div><button class="modal-close">×</button></div><form id="attendance-settings-form" class="form-grid"><label class="attendance-setting-switch"><input type="checkbox" name="enabled" ${s.enabled?"checked":""}><span><strong>เปิดระบบลงเวลา</strong><small>ปิดได้ในช่วงปิดเทอม</small></span></label>${rootAdmin?`<label class="attendance-setting-switch attendance-test-toggle"><input type="checkbox" name="test_center_enabled" ${s.test_center_enabled?"checked":""}><span><strong>🧪 เปิดศูนย์ทดสอบการลงเวลา</strong><small>เฉพาะ Super Admin เท่านั้นที่เปิด/ปิดได้ · ไม่กระทบข้อมูลลงเวลาจริง</small></span></label>`:""}<div class="personnel-form-section"><strong>รูปแบบการลงเวลา</strong></div><div class="attendance-mode-options form-span-2">${[["gps","📍","GPS ปกติ","กดลงเวลาและตรวจ GPS ทันที"],["qr","▦","QR Code + GPS","ต้องสแกน QR ประจำวันก่อนตรวจ GPS"],["face","🙂","Face Verification + GPS","ต้องยืนยันใบหน้าที่ลงทะเบียนก่อนตรวจ GPS"]].map(([v,i,t,d])=>`<label class="attendance-mode-option"><input type="radio" name="attendance_mode" value="${v}" ${mode===v?"checked":""}><span class="attendance-mode-icon">${i}</span><span><strong>${t}</strong><small>${d}</small></span></label>`).join("")}</div><div class="attendance-mode-note form-span-2">เลือกใช้ได้ทีละโหมดเดียว และเมื่อมีคนลงเวลาในวันนั้นแล้ว ระบบจะล็อกโหมดจนจบวัน · GPS เป็นเงื่อนไขบังคับทุกโหมด</div><div class="personnel-form-section"><strong>พิกัดโรงเรียน</strong></div><div class="field"><label>Latitude</label><input class="input" name="school_latitude" type="number" step="0.0000001" value="${s.school_latitude??""}" required></div><div class="field"><label>Longitude</label><input class="input" name="school_longitude" type="number" step="0.0000001" value="${s.school_longitude??""}" required></div><div class="field"><label>รัศมีที่อนุญาต (เมตร)</label><input class="input" name="allowed_radius_m" type="number" min="20" max="5000" value="${s.allowed_radius_m||250}" required></div><div class="field"><label>GPS คลาดเคลื่อนได้ไม่เกิน (เมตร)</label><input class="input" name="max_accuracy_m" type="number" min="10" max="2000" value="${s.max_accuracy_m||150}" required></div><div class="field form-span-2"><button type="button" class="btn btn-secondary" id="attendance-use-current-location">📍 ใช้ตำแหน่งปัจจุบันเป็นพิกัดโรงเรียน</button><span class="helper" id="attendance-location-helper">ควรตั้งค่าขณะอยู่บริเวณโรงเรียนและเปิด GPS แบบแม่นยำ</span></div><div class="personnel-form-section"><strong>ช่วงเวลา</strong></div><div class="field"><label>เปิดเช็กชื่อ</label><input class="input" name="checkin_open_time" type="time" value="${officialAttendanceTime(s.checkin_open_time||"06:00")}" required></div><div class="field"><label>ตรงเวลาถึง</label><input class="input" name="ontime_until" type="time" value="${officialAttendanceTime(s.ontime_until||"08:30")}" required></div><div class="field"><label>ปิดรับเช็กชื่อ</label><input class="input" name="checkin_close_time" type="time" value="${officialAttendanceTime(s.checkin_close_time||"23:59")}" required></div><div class="field"><label>เวลาสิ้นสุดราชการ</label><input class="input" name="work_end_time" type="time" value="${officialAttendanceTime(s.work_end_time||"16:30")}" required></div><div class="field"><label>เปิดใช้ตั้งแต่วันที่</label><input class="input" name="active_from" type="date" value="${s.active_from||""}"></div><div class="field"><label>ถึงวันที่</label><input class="input" name="active_to" type="date" value="${s.active_to||""}"></div><div class="personnel-form-section"><strong>วันปฏิบัติราชการประจำสัปดาห์</strong></div><div class="attendance-weekdays form-span-2">${[["monday","จันทร์"],["tuesday","อังคาร"],["wednesday","พุธ"],["thursday","พฤหัสบดี"],["friday","ศุกร์"],["saturday","เสาร์"],["sunday","อาทิตย์"]].map(([k,l])=>`<label><input type="checkbox" name="${k}" ${s[k]?"checked":""}><span>${l}</span></label>`).join("")}</div></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-settings-save">บันทึกการตั้งค่า</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;
  m.querySelector("#attendance-use-current-location").onclick=e=>{if(!navigator.geolocation)return toast("อุปกรณ์ไม่รองรับ GPS","","error");buttonLoading(e.currentTarget,true,"กำลังหาพิกัด...");navigator.geolocation.getCurrentPosition(pos=>{m.querySelector('[name="school_latitude"]').value=pos.coords.latitude.toFixed(7);m.querySelector('[name="school_longitude"]').value=pos.coords.longitude.toFixed(7);m.querySelector("#attendance-location-helper").textContent=`พิกัดจากเครื่อง · ความแม่นยำประมาณ ±${Math.round(pos.coords.accuracy)} เมตร`;buttonLoading(e.currentTarget,false);},err=>{buttonLoading(e.currentTarget,false);toast("หาพิกัดไม่สำเร็จ",err.code===1?"กรุณาอนุญาตตำแหน่ง":"กรุณาลองใหม่","error");},{enableHighAccuracy:true,timeout:20000,maximumAge:0});};
  m.querySelector("#attendance-settings-save").onclick=async e=>{const form=m.querySelector("#attendance-settings-form");if(!form.reportValidity())return;const f=new FormData(form),latRaw=String(f.get("school_latitude")||"").trim(),lngRaw=String(f.get("school_longitude")||"").trim(),payload={enabled:f.get("enabled")==="on",...(rootAdmin?{test_center_enabled:f.get("test_center_enabled")==="on"}:{}),attendance_mode:String(f.get("attendance_mode")||"gps"),school_latitude:latRaw?Number(latRaw):null,school_longitude:lngRaw?Number(lngRaw):null,allowed_radius_m:Number(f.get("allowed_radius_m")),max_accuracy_m:Number(f.get("max_accuracy_m")),checkin_open_time:f.get("checkin_open_time"),ontime_until:f.get("ontime_until"),checkin_close_time:f.get("checkin_close_time"),work_end_time:f.get("work_end_time"),active_from:f.get("active_from")||null,active_to:f.get("active_to")||null,monday:f.get("monday")==="on",tuesday:f.get("tuesday")==="on",wednesday:f.get("wednesday")==="on",thursday:f.get("thursday")==="on",friday:f.get("friday")==="on",saturday:f.get("saturday")==="on",sunday:f.get("sunday")==="on",updated_by:state.user.id,updated_at:new Date().toISOString()};if(payload.enabled&&(!Number.isFinite(payload.school_latitude)||!Number.isFinite(payload.school_longitude)))return toast("กรุณากำหนดพิกัดโรงเรียน","","error");buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_settings").update(payload).eq("id",1);buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกการตั้งค่าแล้ว",`โหมดหลัก: ${ATTENDANCE_MODE_LABEL[payload.attendance_mode]}`,"success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}
function officialAttendanceDaySettingModal(){
  if(!officialAttendanceCanManageUi())return;const selected=state.officialAttendanceReportDate||officialAttendanceDateValue(),existing=(state.officialAttendanceDaySettings||[]).find(x=>String(x.attendance_date)===selected),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>กำหนดวันเปิด/ปิดพิเศษ</h3><p>ใช้สำหรับวันหยุด ปิดเทอม เปลี่ยนเวลา หรือเปลี่ยนโหมดเฉพาะวัน</p></div><button class="modal-close">×</button></div><form id="attendance-day-form" class="form-grid"><div class="field"><label>วันที่</label><input class="input" name="attendance_date" type="date" value="${existing?.attendance_date||selected}" required></div><div class="field"><label>สถานะ</label><select class="select" name="is_open"><option value="true" ${existing?.is_open!==false?"selected":""}>เปิดลงเวลา</option><option value="false" ${existing?.is_open===false?"selected":""}>ปิดลงเวลา</option></select></div><div class="field form-span-2"><label>รูปแบบการลงเวลาของวันนี้</label><select class="select" name="attendance_mode"><option value="" ${!existing?.attendance_mode?"selected":""}>ใช้ค่ากลางของระบบ (${escapeHtml(ATTENDANCE_MODE_LABEL[state.officialAttendanceSettings?.attendance_mode||"gps"])})</option><option value="gps" ${existing?.attendance_mode==="gps"?"selected":""}>GPS ปกติ</option><option value="qr" ${existing?.attendance_mode==="qr"?"selected":""}>QR Code + GPS</option><option value="face" ${existing?.attendance_mode==="face"?"selected":""}>Face Verification + GPS</option></select><span class="helper">หากมีผู้ลงเวลาแล้ว ระบบจะไม่อนุญาตให้เปลี่ยนโหมดของวันนั้น</span></div><div class="field"><label>เปิดเช็กชื่อ (เว้นว่าง=ค่ากลาง)</label><input class="input" name="checkin_open_time" type="time" value="${existing?.checkin_open_time?officialAttendanceTime(existing.checkin_open_time):""}"></div><div class="field"><label>ตรงเวลาถึง</label><input class="input" name="ontime_until" type="time" value="${existing?.ontime_until?officialAttendanceTime(existing.ontime_until):""}"></div><div class="field"><label>ปิดรับเช็กชื่อ</label><input class="input" name="checkin_close_time" type="time" value="${existing?.checkin_close_time?officialAttendanceTime(existing.checkin_close_time):""}"></div><div class="field"><label>เวลาสิ้นสุดราชการ</label><input class="input" name="work_end_time" type="time" value="${existing?.work_end_time?officialAttendanceTime(existing.work_end_time):""}"></div><div class="field form-span-2"><label>หมายเหตุ</label><input class="input" name="note" value="${escapeHtml(existing?.note||"")}" placeholder="เช่น ปิดภาคเรียน / วันหยุดพิเศษ"></div></form><div class="modal-actions">${existing?`<button class="btn btn-danger" id="attendance-day-delete">ลบค่าพิเศษ</button>`:""}<button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-day-save">บันทึก</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelector("#attendance-day-delete")?.addEventListener("click",async e=>{if(!window.confirm("ลบค่าพิเศษของวันนี้ และกลับไปใช้ค่ากลาง?"))return;buttonLoading(e.currentTarget,true,"กำลังลบ...");const {error}=await supabase.from("official_attendance_day_settings").delete().eq("attendance_date",existing.attendance_date);if(error){buttonLoading(e.currentTarget,false);return toast("ลบไม่สำเร็จ",error.message,"error");}close();await loadOfficialAttendanceWorkspace();await renderDashboard();});m.querySelector("#attendance-day-save").onclick=async e=>{const f=new FormData(m.querySelector("#attendance-day-form")),payload={attendance_date:f.get("attendance_date"),is_open:f.get("is_open")==="true",attendance_mode:f.get("attendance_mode")||null,checkin_open_time:f.get("checkin_open_time")||null,ontime_until:f.get("ontime_until")||null,checkin_close_time:f.get("checkin_close_time")||null,work_end_time:f.get("work_end_time")||null,note:String(f.get("note")||"").trim()||null,updated_by:state.user.id,updated_at:new Date().toISOString()};buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_day_settings").upsert(payload,{onConflict:"attendance_date"});buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกวันพิเศษแล้ว",payload.is_open?`เปิดลงเวลา · ${ATTENDANCE_MODE_LABEL[payload.attendance_mode||state.officialAttendanceSettings?.attendance_mode||"gps"]}`:"วันนี้ปิดลงเวลา","success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}
function officialAttendanceDutyModal(){if(!officialAttendanceCanManageUi())return;const date=state.officialAttendanceReportDate||officialAttendanceDateValue(),m=document.createElement("div");m.className="modal-backdrop";m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>บันทึกไปราชการ / ปฏิบัติงานนอกสถานที่</h3><p>รายการนี้จะไม่นับบุคลากรเป็นผู้ขาดเช็กชื่อในวันดังกล่าว</p></div><button class="modal-close">×</button></div><form id="attendance-duty-form" class="form-grid"><div class="field"><label>วันที่</label><input class="input" name="duty_date" type="date" value="${date}" required></div><div class="field"><label>บุคลากร</label><select class="select" name="user_id" required><option value="">— เลือกบุคลากร —</option>${(state.officialAttendanceRoster||[]).filter(p=>p.role!=="super_admin").map(p=>`<option value="${p.id}">${escapeHtml(p.full_name||p.email||"-")} · ${escapeHtml(officialAttendanceRosterPosition(p.id))}</option>`).join("")}</select></div><div class="field"><label>ประเภท</label><select class="select" name="duty_type"><option value="official_duty">ไปราชการ</option><option value="training">อบรม / สัมมนา</option><option value="other">ปฏิบัติหน้าที่อื่น</option></select></div><div class="field"><label>สถานที่</label><input class="input" name="duty_location" placeholder="เช่น สพป.เชียงใหม่ เขต 3"></div><div class="field form-span-2"><label>หมายเหตุ</label><textarea class="input textarea" name="note" placeholder="เลขคำสั่ง / รายละเอียดเพิ่มเติม"></textarea></div></form><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="attendance-duty-save">บันทึก</button></div></div>`;document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;m.querySelector("#attendance-duty-save").onclick=async e=>{const f=new FormData(m.querySelector("#attendance-duty-form")),uid=f.get("user_id");if(!uid)return toast("กรุณาเลือกบุคลากร","","error");const payload={user_id:uid,duty_date:f.get("duty_date"),duty_type:f.get("duty_type"),duty_location:String(f.get("duty_location")||"").trim()||null,note:String(f.get("note")||"").trim()||null,created_by:state.user.id,updated_by:state.user.id,updated_at:new Date().toISOString()};buttonLoading(e.currentTarget,true,"กำลังบันทึก...");const {error}=await supabase.from("official_attendance_duty_records").upsert(payload,{onConflict:"user_id,duty_date"});buttonLoading(e.currentTarget,false);if(error)return toast("บันทึกไม่สำเร็จ",error.message,"error");close();toast("บันทึกสถานะไปราชการแล้ว","รายการจะถูกนำไปสรุปในรายงานอัตโนมัติ","success");await loadOfficialAttendanceWorkspace();await renderDashboard();};}
async function officialAttendanceSignatureDataUrl(record){if(!record?.signature_path)return null;const key=`${record.signature_bucket||"signatures"}:${record.signature_path}`;if(officialAttendanceSignatureCache.has(key))return officialAttendanceSignatureCache.get(key);const {data,error}=await supabase.storage.from(record.signature_bucket||"signatures").download(record.signature_path);if(error){console.warn("attendance signature download",error);return null;}const url=await blobToDataUrl(data);officialAttendanceSignatureCache.set(key,url);return url;}
function officialAttendancePdfStyles(){return `@font-face{font-family:"TH SarabunIT๙";src:local("TH SarabunIT๙"),local("THSarabunIT๙")}*{box-sizing:border-box}html,body{width:100%;margin:0;padding:0}body{font-family:"TH SarabunIT๙","THSarabunIT๙",serif;color:#111;background:#fff}@page{size:A4 portrait;margin:12mm}.attendance-pdf{width:100%;max-width:100%;margin:0 auto;font-size:14pt;line-height:1.22;overflow:visible}.attendance-pdf-head{text-align:center;margin-bottom:3mm}.attendance-pdf-logo{width:21mm;height:21mm;object-fit:contain}.attendance-pdf-head h1{font-size:19pt;margin:.8mm 0 0}.attendance-pdf-head h2{font-size:17pt;margin:.7mm 0}.attendance-pdf-head p{font-size:13.5pt;margin:0}.attendance-pdf-meta{display:flex;justify-content:center;flex-wrap:wrap;gap:3mm 8mm;margin:2mm 0 3mm;font-size:14pt}.attendance-pdf-table{width:100%;max-width:100%;border-collapse:collapse;table-layout:fixed;border:1px solid #222}.attendance-pdf-table thead{display:table-header-group}.attendance-pdf-table tr{break-inside:avoid;page-break-inside:avoid}.attendance-pdf-table th,.attendance-pdf-table td{border:1px solid #222;padding:1.05mm .65mm;vertical-align:middle;overflow-wrap:anywhere;word-break:normal}.attendance-pdf-table th{text-align:center;font-size:14pt;line-height:1.12;background:#f4f4f4}.attendance-pdf-table td{font-size:14pt;line-height:1.14}.attendance-pdf-center{text-align:center}.attendance-pdf-name{font-size:14.25pt;font-weight:700;line-height:1.1}.attendance-pdf-table small{font-size:11.5pt;line-height:1.05}.attendance-pdf-sign{height:10mm;text-align:center;padding-left:.35mm!important;padding-right:.35mm!important}.attendance-pdf-sign img{max-height:8.8mm;max-width:22mm;object-fit:contain}.attendance-pdf-note-cell{font-size:13.5pt!important;line-height:1.12!important}.attendance-pdf-summary{margin-top:4mm;border:1px solid #333;padding:2.5mm;break-inside:avoid}.attendance-pdf-summary-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5mm 3mm;font-size:14pt}.attendance-pdf-note{margin-top:4mm;break-inside:avoid}.attendance-pdf-note h3{font-size:15.5pt;margin:0 0 1.5mm}.attendance-pdf-note ol{margin:0;padding-left:8mm;font-size:14pt}.attendance-pdf-footer{margin-top:4mm;text-align:right;font-size:11.5pt;color:#444}.attendance-summary-pdf-table th,.attendance-summary-pdf-table td{font-size:13.5pt;padding:1.35mm .7mm}.attendance-summary-pdf-table td:not(:first-child){text-align:center}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.attendance-pdf{width:100%}}`;}
async function officialAttendanceDailyPdf(date){const summary=officialAttendanceSummaryForDate(date),rows=summary.rows,logo=await schoolLogoDataUrl(),sigMap=new Map();for(const x of rows){if(x.record){const url=await officialAttendanceSignatureDataUrl(x.record);if(url)sigMap.set(x.record.id,url);}}const dutyRows=rows.filter(x=>x.code==="duty"),dutySection=dutyRows.length?`<section class="attendance-pdf-note"><h3>ผู้ไปราชการ / อบรม / ปฏิบัติหน้าที่นอกสถานที่ (${dutyRows.length} คน)</h3><ol>${dutyRows.map(x=>`<li><strong>${escapeHtml(x.user.full_name||x.user.email||"-")}</strong> — ${escapeHtml(ATTENDANCE_DUTY_LABEL[x.duty?.duty_type]||"ไปราชการ")}${x.duty?.duty_location?` — ${escapeHtml(x.duty.duty_location)}`:""}${x.duty?.note?` — ${escapeHtml(x.duty.note)}`:""}</li>`).join("")}</ol></section>`:"";const body=`<article class="attendance-pdf"><header class="attendance-pdf-head">${logo?`<img class="attendance-pdf-logo" src="${logo}" alt="ตราโรงเรียน">`:""}<h1>${escapeHtml(schoolName())}</h1><h2>บัญชีลงเวลาปฏิบัติราชการ</h2><p>${escapeHtml(schoolAddress())} · ${escapeHtml(educationOffice())}</p></header><div class="attendance-pdf-meta"><span><strong>วันที่</strong> ${officialAttendanceThaiDate(date)}</span><span><strong>บุคลากรที่ต้องลงเวลา</strong> ${summary.total} คน</span></div><table class="attendance-pdf-table"><colgroup><col style="width:5%"><col style="width:25%"><col style="width:12%"><col style="width:15%"><col style="width:12%"><col style="width:15%"><col style="width:16%"></colgroup><thead><tr><th>ที่</th><th>ชื่อ–นามสกุล</th><th>เวลาเข้า</th><th>ลายเซ็น</th><th>เวลากลับ</th><th>ลายเซ็น</th><th>หมายเหตุ</th></tr></thead><tbody>${rows.map(x=>{const img=x.record?sigMap.get(x.record.id):null;return `<tr><td class="attendance-pdf-center">${x.arrivalOrder||"—"}</td><td><div class="attendance-pdf-name">${escapeHtml(x.user.full_name||x.user.email||"-")}</div><small>${escapeHtml(x.position||"")}</small></td><td class="attendance-pdf-center">${x.record?`${officialAttendanceTime(x.record.checkin_at,true)} น.`:"—"}</td><td class="attendance-pdf-sign">${img?`<img src="${img}" alt="ลายเซ็น">`:"—"}</td><td class="attendance-pdf-center">${x.record?`${officialAttendanceTime(x.record.work_end_time_snapshot)} น.`:"—"}</td><td class="attendance-pdf-sign">${img?`<img src="${img}" alt="ลายเซ็น">`:"—"}</td><td class="attendance-pdf-note-cell">${escapeHtml(x.note||"—")}</td></tr>`;}).join("")}</tbody></table><section class="attendance-pdf-summary"><div class="attendance-pdf-summary-grid"><span>บุคลากรทั้งหมด <strong>${summary.total}</strong> คน</span><span>ลงเวลา <strong>${summary.checked}</strong> คน</span><span>ตรงเวลา <strong>${summary.onTime}</strong> คน</span><span>สาย <strong>${summary.late}</strong> คน</span><span>ลา <strong>${summary.leave}</strong> คน</span><span>ไปราชการ <strong>${summary.duty}</strong> คน</span></div></section>${dutySection}<div class="attendance-pdf-footer">สร้างจาก BNK School OS · ระบบลงเวลาปฏิบัติราชการ</div></article>`;openPrintPreview(body,officialAttendancePdfStyles(),`บัญชีลงเวลาปฏิบัติราชการ ${officialAttendanceThaiDate(date)}`);}
async function officialAttendanceSummaryPdf(start,end,title){const data=officialAttendanceMonthlySummary(start,end),logo=await schoolLogoDataUrl(),body=`<article class="attendance-pdf"><header class="attendance-pdf-head">${logo?`<img class="attendance-pdf-logo" src="${logo}" alt="ตราโรงเรียน">`:""}<h1>${escapeHtml(schoolName())}</h1><h2>${escapeHtml(title)}</h2><p>${escapeHtml(schoolAddress())} · ${escapeHtml(educationOffice())}</p></header><div class="attendance-pdf-meta"><span>${officialAttendanceThaiDate(start)} – ${officialAttendanceThaiDate(end)}</span><span>วันปฏิบัติราชการ <strong>${data.workdays.length}</strong> วัน · ผ่านแล้ว ${data.elapsedWorkdays.length} วัน</span></div><table class="attendance-pdf-table attendance-summary-pdf-table"><thead><tr><th style="width:9mm">ที่</th><th>ชื่อ–นามสกุล / ตำแหน่ง</th><th style="width:18mm">วันเต็ม</th><th style="width:18mm">ลงเวลา</th><th style="width:15mm">สาย</th><th style="width:15mm">ลา</th><th style="width:21mm">ไปราชการ</th><th style="width:21mm">ขาดเช็กชื่อ</th></tr></thead><tbody>${data.rows.map((x,i)=>`<tr><td class="attendance-pdf-center">${i+1}</td><td><strong>${escapeHtml(x.user.full_name||x.user.email||"-")}</strong><br><small>${escapeHtml(x.position||"")}</small></td><td>${x.expected}</td><td>${x.checked}</td><td>${x.late}</td><td>${x.leave}</td><td>${x.duty}</td><td>${x.missing}</td></tr>`).join("")}</tbody></table><div class="attendance-pdf-footer">หมายเหตุ: วันลาอ้างอิงจากคำขอลาที่อนุมัติแล้ว · ไปราชการอ้างอิงจากรายการที่ฝ่ายบุคคลบันทึก</div></article>`;openPrintPreview(body,officialAttendancePdfStyles(),title);}
async function officialAttendanceExportCurrent(){const view=state.officialAttendanceView||"daily";if(view==="daily")return officialAttendanceDailyPdf(state.officialAttendanceReportDate);if(view==="monthly"){const r=officialAttendanceRangeForMonth();return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาประจำเดือน ${state.officialAttendanceReportMonth}`);}if(view==="term"){const r=officialAttendanceRangeForTerm(state.officialAttendanceReportAcademicYear,state.officialAttendanceReportSemester);return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาภาคเรียนที่ ${state.officialAttendanceReportSemester} ปีการศึกษา ${state.officialAttendanceReportAcademicYear}`);}const r=officialAttendanceRangeForYear();return officialAttendanceSummaryPdf(r.start,r.end,`สรุปการลงเวลาปีการศึกษา ${state.officialAttendanceReportAcademicYear}`);}

async function officialAttendanceCancelRecordModal(recordId){
  if(!officialAttendanceCanCancelUi())return toast("ไม่มีสิทธิ์ยกเลิกการลงเวลา","สิทธิ์นี้สำหรับฝ่ายบุคคล/เจ้าหน้าที่บุคคล และ Super Admin","error");
  const record=(state.officialAttendanceRecords||[]).find(r=>r.id===recordId);
  if(!record)return toast("ไม่พบรายการลงเวลา","รายการอาจถูกยกเลิกไปแล้ว กรุณารีเฟรชข้อมูล","error");
  const person=(state.officialAttendanceRoster||[]).find(p=>p.id===record.user_id),name=record.person_name||person?.full_name||person?.email||"บุคลากร";
  const m=document.createElement("div");m.className="modal-backdrop";
  m.innerHTML=`<div class="modal"><div class="modal-head"><div><h3>ยกเลิกการลงเวลา</h3><p>รายการจะถูกนำออกจากสถิติและ PDF แต่ระบบจะเก็บประวัติการยกเลิกไว้ตรวจสอบย้อนหลัง</p></div><button class="modal-close">×</button></div><div class="attendance-cancel-summary"><strong>${escapeHtml(name)}</strong><span>${officialAttendanceThaiDate(record.attendance_date)} · ${officialAttendanceTime(record.checkin_at,true)} น. · ${escapeHtml(officialAttendanceMethodLabel(record))}</span><small>${record.status==="late"?"สถานะเดิม: สาย":"สถานะเดิม: ตรงเวลา"}</small></div><div class="field"><label>เหตุผลการยกเลิก <span class="required">*</span></label><textarea class="input textarea" id="attendance-cancel-reason" maxlength="500" placeholder="เช่น กดลงเวลาโดยไม่ตั้งใจ / ทดสอบระบบ / บันทึกผิดรายการ"></textarea><span class="helper">หลังยกเลิก บุคลากรสามารถลงเวลาใหม่ในวันเดิมได้ หากระบบยังเปิดรับและผ่านเงื่อนไขของโหมดวันนั้น</span></div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-danger" id="attendance-cancel-confirm">ยืนยันยกเลิกการลงเวลา</button></div></div>`;
  document.body.appendChild(m);const close=()=>m.remove();m.querySelector(".modal-close").onclick=close;m.querySelector(".modal-cancel").onclick=close;
  m.querySelector("#attendance-cancel-confirm").onclick=async e=>{const reason=String(m.querySelector("#attendance-cancel-reason").value||"").trim();if(reason.length<3)return toast("กรุณาระบุเหตุผล","อย่างน้อย 3 ตัวอักษร เพื่อเก็บเป็นหลักฐานการแก้ไข","error");if(!window.confirm(`ยืนยันยกเลิกการลงเวลาของ ${name} ?`))return;buttonLoading(e.currentTarget,true,"กำลังยกเลิก...");const {error}=await supabase.rpc("cancel_official_attendance_record",{p_record_id:record.id,p_reason:reason});buttonLoading(e.currentTarget,false);if(error)return toast("ยกเลิกไม่สำเร็จ",error.message,"error");close();toast("ยกเลิกการลงเวลาแล้ว",`${name} สามารถลงเวลาใหม่ได้ หากระบบยังเปิดรับ` ,"success");await loadOfficialAttendanceWorkspace();await renderDashboard();};
}

function bindOfficialAttendanceEvents(){
  document.querySelector("#official-attendance-checkin")?.addEventListener("click",e=>officialAttendanceCheckIn(e.currentTarget));
  document.querySelector("#official-attendance-qr-scan")?.addEventListener("click",officialAttendanceQrScanModal);
  document.querySelector("#official-attendance-face-register")?.addEventListener("click",officialAttendanceFaceRegistrationModal);
  document.querySelector("#official-attendance-face-checkin")?.addEventListener("click",officialAttendanceFaceCheckInModal);
  document.querySelector("#official-attendance-face-delete")?.addEventListener("click",e=>officialAttendanceDeleteFaceRegistration(e.currentTarget));
  document.querySelector("#attendance-qr-rotate")?.addEventListener("click",e=>officialAttendanceRotateQr(e.currentTarget));
  document.querySelector("#attendance-face-manage")?.addEventListener("click",officialAttendanceFaceManagerModal);
  document.querySelector("#attendance-test-center")?.addEventListener("click",officialAttendanceTestCenterModal);
  document.querySelector("#attendance-retry-load")?.addEventListener("click",async e=>{buttonLoading(e.currentTarget,true,"กำลังโหลด...");state.officialAttendanceLoadError=null;await renderDashboard();});
  document.querySelector("#attendance-settings-open")?.addEventListener("click",officialAttendanceSettingsModal);
  document.querySelector("#attendance-day-setting-open")?.addEventListener("click",officialAttendanceDaySettingModal);
  document.querySelector("#attendance-duty-open")?.addEventListener("click",officialAttendanceDutyModal);
  document.querySelectorAll("[data-attendance-view]").forEach(b=>b.addEventListener("click",()=>{state.officialAttendanceView=b.dataset.attendanceView;renderDashboard();}));
  document.querySelector("#attendance-report-date")?.addEventListener("change",async e=>{state.officialAttendanceReportDate=e.currentTarget.value;const ay=officialAttendanceAcademicYearForDate(state.officialAttendanceReportDate);if(ay!==Number(state.officialAttendanceReportAcademicYear)){state.officialAttendanceReportAcademicYear=ay;await loadOfficialAttendanceWorkspace();}renderDashboard();});
  document.querySelector("#attendance-report-month")?.addEventListener("change",async e=>{state.officialAttendanceReportMonth=e.currentTarget.value;const ay=officialAttendanceAcademicYearForDate(`${e.currentTarget.value}-15`);if(ay!==Number(state.officialAttendanceReportAcademicYear)){state.officialAttendanceReportAcademicYear=ay;await loadOfficialAttendanceWorkspace();}renderDashboard();});
  document.querySelector("#attendance-report-year")?.addEventListener("change",async e=>{state.officialAttendanceReportAcademicYear=Number(e.currentTarget.value);await loadOfficialAttendanceWorkspace();renderDashboard();});
  document.querySelector("#attendance-report-semester")?.addEventListener("change",e=>{state.officialAttendanceReportSemester=Number(e.currentTarget.value);renderDashboard();});
  document.querySelector("#attendance-export-report")?.addEventListener("click",officialAttendanceExportCurrent);
  document.querySelectorAll("[data-attendance-cancel-record]").forEach(b=>b.addEventListener("click",()=>officialAttendanceCancelRecordModal(b.dataset.attendanceCancelRecord)));
  document.querySelectorAll("[data-attendance-duty-delete]").forEach(b=>b.addEventListener("click",async()=>{if(!window.confirm("ลบสถานะไปราชการรายการนี้?"))return;const {error}=await supabase.from("official_attendance_duty_records").delete().eq("id",b.dataset.attendanceDutyDelete);if(error)return toast("ลบไม่สำเร็จ",error.message,"error");await loadOfficialAttendanceWorkspace();await renderDashboard();}));
  officialAttendanceRenderQrCode();
}


function moduleView(code) {
  const module = state.modules.find(m => m.code === code);
  if (!module) return `<div class="empty"><strong>ไม่พบระบบย่อย</strong></div>`;
  if (code === "academic_calendar") return academicCalendarWorkspaceHtml(module);
  if (code === "academic_registration") return academicRegistrationWorkspaceHtml(module);
  if (code === "academic_submissions") return academicSubmissionWorkspaceHtml(module);
  if (code === "lesson_plans") return lessonWorkspaceHtml(module);
  if (code === "personnel_records") return personnelWorkspaceHtml(module);
  if (code === "leave_management") return leaveWorkspaceHtml(module);
  if (code === "official_attendance") return officialAttendanceWorkspaceHtml(module);
  if (code === "timetable_management") return timetableWorkspaceHtml(module);
  if (code === "substitute_teaching") return substituteWorkspaceHtml(module);
  if (code === "project_management") return projectWorkspaceHtml(module);
  if (code === "home_visit_management") return homeVisitWorkspaceHtml(module);
  if (code === "student_registry") return studentRegistryWorkspaceHtml(module);
  if (code === "student_cards") return studentCardWorkspaceHtml(module);
  return `<section class="panel"><div class="empty"><strong>${escapeHtml(module.name_th)}</strong><span>Module นี้ยังไม่มีหน้าทำงานเฉพาะ</span></div></section>`;
}

function lessonPlanModal(plan = null, requestedType = null) {
  const p = plan || {};
  const type = plan?.plan_type || requestedType || state.lessonPlanMode || "weekly";
  const semesterPlan = type === "semester";
  const existingFiles = plan && state.lessonDetail?.plan?.id === plan.id ? (state.lessonDetail.files || []) : [];
  const modal = document.createElement("div");
  modal.className = "modal-backdrop";
  modal.dataset.attachmentMethod = "pdf";

  const weeklyFields = `
      <div class="form-row"><div class="field"><label>สัปดาห์ที่</label><input class="input" name="week_number" type="number" min="1" value="${escapeHtml(p.week_number || "")}"></div><div class="field"><label>วันที่ใช้สอน</label><input class="input" name="teach_date" type="date" required value="${escapeHtml(p.teach_date || "")}"></div></div>
      <div class="field"><label>หน่วยการเรียนรู้</label><input class="input" name="learning_unit" value="${escapeHtml(p.learning_unit || "")}"></div>
      <div class="field"><label>เรื่องที่สอน</label><input class="input" name="topic" required value="${escapeHtml(p.topic || "")}"></div>
      <div class="field"><label>จุดประสงค์การเรียนรู้</label><textarea class="input textarea" name="learning_objectives" required>${escapeHtml(p.learning_objectives || "")}</textarea></div>
      <div class="field"><label>สาระ/เนื้อหาสำคัญ</label><textarea class="input textarea" name="content_summary">${escapeHtml(p.content_summary || "")}</textarea></div>
      <div class="field"><label>กิจกรรมการเรียนรู้</label><textarea class="input textarea" name="activities">${escapeHtml(p.activities || "")}</textarea></div>
      <div class="field"><label>การวัดและประเมินผล</label><textarea class="input textarea" name="assessment">${escapeHtml(p.assessment || "")}</textarea></div>`;

  const existingAttachments = existingFiles.length
    ? `<div class="attached-files-summary"><div class="attached-files-title"><strong>✓ แนบอยู่แล้ว ${existingFiles.length} รายการ</strong><span>เอกสารเหล่านี้ถูกบันทึกในระบบแล้ว</span></div>${existingFiles.map(f => {
        const drive = f.attachment_type === "google_drive";
        return `<div class="attached-file-chip ${drive ? "drive" : ""}"><span>${drive ? "DRIVE" : "PDF"}</span><strong>${escapeHtml(f.file_name)}</strong><small>${drive ? "Google Drive Link" : (f.file_size ? `${(f.file_size/1024/1024).toFixed(2)} MB` : "PDF")}</small></div>`;
      }).join("")}</div>`
    : `<div class="no-file-yet">ยังไม่มีเอกสารแนบในแผนนี้</div>`;

  modal.innerHTML = `<div class="modal modal-wide"><div class="modal-head"><div><span class="form-type-badge">${escapeHtml(lessonPlanTypeLabel(type))}</span><h3>${plan ? `แก้ไข${lessonPlanTypeLabel(type)}` : `สร้าง${lessonPlanTypeLabel(type)}ใหม่`}</h3><p>${semesterPlan ? "กรอกข้อมูลรายวิชา แล้วเลือกแนบ PDF หรือ Google Drive สำหรับแผนทั้งภาคเรียน" : "บันทึกเป็นฉบับร่างก่อนส่งเข้าสู่ Workflow ได้"}</p></div><button class="modal-close">×</button></div>
    <form id="lesson-form" class="form-grid" data-plan-type="${type}">
      <div class="form-row"><div class="field"><label>ปีการศึกษา</label><input class="input" name="academic_year" required value="${escapeHtml(p.academic_year || "2569")}"></div><div class="field"><label>ภาคเรียน</label><select class="select" name="semester"><option value="1" ${p.semester==1?'selected':''}>1</option><option value="2" ${p.semester==2?'selected':''}>2</option><option value="3" ${p.semester==3?'selected':''}>3</option></select></div></div>
      <div class="form-row"><div class="field"><label>รหัสวิชา</label><input class="input" name="subject_code" ${semesterPlan ? "required" : ""} value="${escapeHtml(p.subject_code || "")}"></div><div class="field"><label>ชื่อวิชา</label><input class="input" name="subject_name" required value="${escapeHtml(p.subject_name || "")}"></div></div>
      <div class="field"><label>ชั้น/ระดับที่สอน</label><input class="input" name="class_level" ${semesterPlan ? "required" : ""} value="${escapeHtml(p.class_level || "")}" placeholder="เช่น ม.2/1"></div>
      ${semesterPlan ? `<div class="semester-form-note"><strong>แผนรายภาคเรียน</strong><span>ไม่ต้องระบุสัปดาห์ วันที่สอน หน่วยการเรียนรู้ เรื่อง จุดประสงค์ เนื้อหา กิจกรรม หรือการวัดผล — รายละเอียดทั้งหมดให้อยู่ในเอกสารที่แนบ</span></div>` : weeklyFields}

      <div class="field attachment-field">
        <label>เอกสารแผนการสอน</label>
        ${existingAttachments}
        <div class="attachment-method-tabs">
          <button type="button" class="attachment-method active" data-attachment-method="pdf"><span>PDF</span><strong>อัปโหลด PDF</strong><small>เก็บใน Supabase</small></button>
          <button type="button" class="attachment-method" data-attachment-method="google_drive"><span>G</span><strong>Google Drive Link</strong><small>ประหยัด Storage</small></button>
        </div>

        <div id="attachment-pdf-pane" class="attachment-pane">
          <label class="upload-zone"><input id="lesson-pdfs" type="file" accept="application/pdf,.pdf" multiple><strong>＋ เลือก PDF เพิ่ม</strong><span>รองรับหลายไฟล์ ไฟล์ละไม่เกิน 20 MB</span></label>
          <div id="selected-pdf-preview" class="selected-file-preview"><span>ยังไม่ได้เลือกไฟล์ใหม่</span></div>
        </div>

        <div id="attachment-drive-pane" class="attachment-pane hidden">
          <div class="drive-link-box">
            <div class="field"><label>ลิงก์ Google Drive</label><input class="input" id="drive-url" type="url" inputmode="url" placeholder="https://drive.google.com/file/d/..."></div>
            <div class="field"><label>ชื่อเอกสาร <span class="optional">(ไม่บังคับ)</span></label><input class="input" id="drive-label" maxlength="160" placeholder="เช่น แผนการสอนรายภาคเรียน วิชาคณิตศาสตร์"></div>
            <div class="drive-permission-warning"><strong>สำคัญ: ตรวจสิทธิ์การแชร์ก่อนส่ง</strong><span>ตั้งค่า Google Drive ให้หัวหน้ากลุ่มงานและผู้บริหารเปิดดูได้ เช่น “Anyone with the link can view” หรือแชร์ให้บัญชีโรงเรียนโดยตรง</span></div>
          </div>
        </div>
      </div>
    </form>
    <div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-secondary" id="save-draft">บันทึกฉบับร่าง</button><button class="btn btn-primary" id="save-submit">บันทึกและส่งตรวจ</button></div></div>`;

  document.body.appendChild(modal);
  const close = () => modal.remove();
  modal.querySelector(".modal-close").addEventListener("click", close);
  modal.querySelector(".modal-cancel").addEventListener("click", close);
  modal.addEventListener("click", e => { if (e.target === modal) close(); });

  modal.querySelectorAll("[data-attachment-method]").forEach(btn => btn.addEventListener("click", () => {
    const method = btn.dataset.attachmentMethod;
    modal.dataset.attachmentMethod = method;
    modal.querySelectorAll("[data-attachment-method]").forEach(x => x.classList.toggle("active", x === btn));
    modal.querySelector("#attachment-pdf-pane").classList.toggle("hidden", method !== "pdf");
    modal.querySelector("#attachment-drive-pane").classList.toggle("hidden", method !== "google_drive");
  }));

  modal.querySelector("#lesson-pdfs").addEventListener("change", e => {
    const files = [...e.currentTarget.files];
    const preview = modal.querySelector("#selected-pdf-preview");
    preview.innerHTML = files.length
      ? `<strong>เลือกเพิ่ม ${files.length} ไฟล์</strong>${files.map(f => `<div class="selected-file-row"><span>✓</span><span>${escapeHtml(f.name)}</span><small>${(f.size/1024/1024).toFixed(2)} MB</small></div>`).join("")}`
      : `<span>ยังไม่ได้เลือกไฟล์ใหม่</span>`;
  });

  modal.querySelector("#save-draft").addEventListener("click", e => saveLessonPlanFromModal(modal, plan, false, e.currentTarget));
  modal.querySelector("#save-submit").addEventListener("click", e => saveLessonPlanFromModal(modal, plan, true, e.currentTarget));
}

function normalizeGoogleDriveUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  let url;
  try { url = new URL(raw); } catch { return null; }
  const host = url.hostname.toLowerCase();
  if (url.protocol !== "https:" || !["drive.google.com", "docs.google.com"].includes(host)) return null;
  return url.toString();
}

async function saveLessonPlanFromModal(modal, existing, submitAfter, button) {
  const form = modal.querySelector("#lesson-form");
  if (!form.reportValidity()) return;
  const fd = new FormData(form);
  const type = form.dataset.planType || existing?.plan_type || "weekly";
  const semesterPlan = type === "semester";
  const attachmentMethod = modal.dataset.attachmentMethod || "pdf";
  const pdfs = attachmentMethod === "pdf" ? [...modal.querySelector("#lesson-pdfs").files] : [];
  const driveRaw = attachmentMethod === "google_drive" ? modal.querySelector("#drive-url").value : "";
  const driveUrl = driveRaw ? normalizeGoogleDriveUrl(driveRaw) : null;
  const driveLabel = String(modal.querySelector("#drive-label")?.value || "").trim();

  for (const file of pdfs) {
    if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) return toast("ไฟล์ไม่ถูกต้อง", "อนุญาตเฉพาะ PDF", "error");
    if (file.size > 20 * 1024 * 1024) return toast("ไฟล์ใหญ่เกินไป", `${file.name} เกิน 20 MB`, "error");
  }

  if (driveRaw && !driveUrl) {
    return toast("ลิงก์ Google Drive ไม่ถูกต้อง", "กรุณาใช้ลิงก์ https://drive.google.com หรือ https://docs.google.com", "error");
  }

  const existingAttachmentCount =
    existing && state.lessonDetail?.plan?.id === existing.id
      ? (state.lessonDetail.files?.length || 0)
      : 0;

  const newAttachmentCount = pdfs.length + (driveUrl ? 1 : 0);
  if (submitAfter && existingAttachmentCount + newAttachmentCount === 0) {
    return toast("ยังส่งแผนไม่ได้", "กรุณาแนบ PDF หรือ Google Drive Link อย่างน้อย 1 รายการก่อนส่ง", "error");
  }

  const commonPayload = {
    academic_year: String(fd.get("academic_year")).trim(),
    semester: Number(fd.get("semester")),
    subject_code: String(fd.get("subject_code") || "").trim() || null,
    subject_name: String(fd.get("subject_name")).trim(),
    class_level: String(fd.get("class_level") || "").trim() || null,
  };

  const payload = semesterPlan
    ? {
        ...commonPayload,
        week_number: null,
        teach_date: null,
        learning_unit: null,
        topic: null,
        learning_objectives: null,
        content_summary: null,
        activities: null,
        assessment: null,
      }
    : {
        ...commonPayload,
        week_number: fd.get("week_number") ? Number(fd.get("week_number")) : null,
        teach_date: fd.get("teach_date") || null,
        learning_unit: String(fd.get("learning_unit") || "").trim() || null,
        topic: String(fd.get("topic") || "").trim() || null,
        learning_objectives: String(fd.get("learning_objectives") || "").trim() || null,
        content_summary: String(fd.get("content_summary") || "").trim() || null,
        activities: String(fd.get("activities") || "").trim() || null,
        assessment: String(fd.get("assessment") || "").trim() || null,
      };

  if (!existing) payload.plan_type = type;

  buttonLoading(button, true, submitAfter ? "กำลังบันทึกและส่ง..." : "กำลังบันทึก...");
  let plan;
  let result;
  if (existing) {
    result = await supabase.from("lesson_plans").update(payload).eq("id", existing.id).select().single();
  } else {
    result = await supabase.from("lesson_plans").insert(payload).select().single();
  }
  if (result.error) {
    buttonLoading(button, false);
    return toast("บันทึกไม่สำเร็จ", result.error.message, "error");
  }
  plan = result.data;

  try {
    for (const file of pdfs) await uploadLessonPdf(plan, file);
    if (driveUrl) await addGoogleDriveAttachment(plan, driveUrl, driveLabel);

    if (submitAfter) {
      const { error } = await supabase.rpc("submit_lesson_plan", { p_lesson_plan_id: plan.id });
      if (error) throw error;
    }
  } catch (error) {
    buttonLoading(button, false);
    toast("บันทึกข้อมูลแล้ว แต่ขั้นตอนต่อไม่สำเร็จ", error.message, "error");
    return;
  }

  buttonLoading(button, false);
  modal.remove();
  state.selectedLessonPlanId = plan.id;
  state.lessonPlanMode = type;
  toast(
    submitAfter ? "ส่งแผนแล้ว" : "บันทึกฉบับร่างแล้ว",
    submitAfter ? (approvalIsParallel("lesson_plans") ? "เปิดช่องรับรองให้ผู้ตรวจที่เกี่ยวข้องแล้ว" : "ระบบแจ้งผู้ตรวจลำดับถัดไปแล้ว") : "คุณสามารถกลับมาแก้ไขและส่งภายหลังได้",
    "success"
  );
  await renderDashboard();
}

async function uploadLessonPdf(plan, file) {
  // Storage object keys use ASCII-only internal names.
  // The original Thai filename is kept in lesson_plan_files.file_name for display.
  const path = `${state.user.id}/${plan.id}/${crypto.randomUUID()}.pdf`;
  const { error: uploadError } = await supabase.storage.from("lesson-plans").upload(path, file, { contentType: "application/pdf", upsert: false });
  if (uploadError) throw uploadError;
  const { error: metaError } = await supabase.from("lesson_plan_files").insert({ lesson_plan_id: plan.id, uploaded_by: state.user.id, bucket_id: "lesson-plans", storage_path: path, file_name: file.name, mime_type: "application/pdf", file_size: file.size, attachment_type: "pdf", external_url: null });
  if (metaError) {
    await supabase.storage.from("lesson-plans").remove([path]);
    throw metaError;
  }
}

async function addGoogleDriveAttachment(plan, url, label) {
  const fileName = label || `Google Drive — ${plan.subject_name || "แผนการสอน"}`;
  const { error } = await supabase.from("lesson_plan_files").insert({
    lesson_plan_id: plan.id,
    uploaded_by: state.user.id,
    bucket_id: null,
    storage_path: null,
    file_name: fileName,
    mime_type: null,
    file_size: null,
    attachment_type: "google_drive",
    external_url: url,
  });
  if (error) throw error;
}

async function openPrivateFile(file) {
  if (file.attachment_type === "google_drive") {
    const url = normalizeGoogleDriveUrl(file.external_url);
    if (!url) return toast("เปิดลิงก์ไม่ได้", "ลิงก์ Google Drive ไม่ถูกต้อง", "error");
    window.open(url, "_blank", "noopener,noreferrer");
    return;
  }

  const { data, error } = await supabase.storage.from(file.bucket_id || "lesson-plans").download(file.storage_path);
  if (error) return toast("เปิดไฟล์ไม่สำเร็จ", error.message, "error");
  const url = URL.createObjectURL(data);
  window.open(url, "_blank", "noopener,noreferrer");
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

async function deleteLessonFile(file) {
  const label = file.attachment_type === "google_drive" ? "ลิงก์" : "ไฟล์";
  if (!window.confirm(`ลบ${label} ${file.file_name} ?`)) return;

  if (file.attachment_type !== "google_drive" && file.storage_path) {
    const { error: storageError } = await supabase.storage.from(file.bucket_id || "lesson-plans").remove([file.storage_path]);
    if (storageError) return toast("ลบไฟล์ไม่สำเร็จ", storageError.message, "error");
  }

  const { error } = await supabase.from("lesson_plan_files").delete().eq("id", file.id);
  if (error) return toast("ลบเอกสารแนบไม่สำเร็จ", error.message, "error");
  toast("ลบเอกสารแนบแล้ว", "", "success");
  await renderDashboard();
}

async function deleteDraftLessonPlan() {
  const p=state.lessonDetail?.plan;
  if(!p)return;
  if(!canDeleteLessonPlanUi(p))return toast("ไม่มีสิทธิ์ลบแผนนี้","เฉพาะเจ้าของแผน หัวหน้าวิชาการ ผู้บริหาร หรือ Super Admin ตามสิทธิ์ที่กำหนด","error");
  const label=`${p.subject_name}${p.plan_type==="semester"?" — แผนรายภาคเรียน":` — ${p.topic||"แผนรายสัปดาห์"}`}`;
  secureDeleteModal({
    title:"ลบแผนการสอน",
    description:label,
    warning:p.status==="draft"||p.status==="revision_requested"
      ? "แผน Timeline และเอกสารแนบที่ผูกกับรายการนี้จะถูกลบออกจากระบบด้วย"
      : "แผนนี้ถูกส่งเข้าสู่ Workflow แล้ว เมื่อลบ Timeline การตรวจ เอกสารแนบ และ Approved PDF (ถ้ามี) จะถูกลบตามไปด้วย และต้องสร้าง/ส่งแผนใหม่หากต้องการใช้งานอีกครั้ง",
    action:async client=>{
      const paths=(state.lessonDetail?.files||[]).map(f=>f.storage_path).filter(Boolean);
      if(paths.length){
        const {error}=await client.storage.from("lesson-plans").remove(paths);
        if(error)throw new Error(`ลบไฟล์แนบไม่สำเร็จ: ${error.message}`);
      }
      const approved=state.lessonDetail?.approvedDocument;
      if(approved?.storage_path){
        const {error}=await client.storage.from(approved.bucket_id||"approved-lesson-plans").remove([approved.storage_path]);
        if(error&&isSuperAdminUser())throw new Error(`ลบ Approved PDF ไม่สำเร็จ: ${error.message}`);
      }
      const {error}=await client.from("lesson_plans").delete().eq("id",p.id);
      if(error)throw error;
    },
    afterDelete:async()=>{
      state.selectedLessonPlanId=null;state.lessonDetail=null;
      toast("ลบแผนการสอนแล้ว","ระบบบันทึกประวัติการลบไว้ใน Audit Log","success");
      await renderDashboard();
    }
  });
}

async function submitSelectedLessonPlan() {
  const p = state.lessonDetail?.plan;
  if (!p) return;
  if (!(state.lessonDetail?.files?.length > 0)) {
    return toast("ยังส่งแผนไม่ได้", "กรุณาแนบ PDF หรือ Google Drive Link อย่างน้อย 1 รายการก่อนส่ง", "error");
  }
  if (!window.confirm("ส่งแผนเข้าสู่ขั้นตอนตรวจสอบหรือไม่? หลังส่งแล้วจะไม่สามารถแก้ไขได้จนกว่าจะถูกส่งกลับ")) return;
  const { error } = await supabase.rpc("submit_lesson_plan", { p_lesson_plan_id: p.id });
  if (error) return toast("ส่งแผนไม่สำเร็จ", error.message, "error");
  toast("ส่งแผนเรียบร้อย", approvalIsParallel("lesson_plans") ? "ผู้ตรวจที่เกี่ยวข้องสามารถตรวจและลงนามได้ทันทีโดยไม่ต้องรอคิว" : "ผู้ตรวจลำดับถัดไปจะได้รับการแจ้งเตือน", "success");
  await renderDashboard();
}

function reviewModal(role) {
  const p = state.lessonDetail?.plan;
  if (!p) return;
  const director = role === "director";
  const reviewerTitle = director ? "ผู้บริหาร" : "หัวหน้ากลุ่มงานวิชาการ";
  const autoPolicy=director?currentApprovalPolicy("lesson_plans"):null;
  const currentVersion=Number(p.approval_version||1);
  const directorSlot=director?(state.lessonDetail?.approvalSlots||[]).find(x=>Number(x.document_version||1)===currentVersion&&x.slot_code==="director"):null;
  const snapshottedSignatureId=directorSlot?.actor_user_id===state.user?.id?directorSlot?.signature_id:null;
  const preferredSignatureId=snapshottedSignatureId||(director&&autoPolicy?.enabled&&autoPolicy?.auto_sign?autoPolicy.signature_id:null)||(state.signatures.find(s=>s.is_default)?.id||null);
  const modal = document.createElement("div");
  modal.className = "modal-backdrop";
  modal.innerHTML = `<div class="modal"><div class="modal-head"><div><h3>${director ? "อนุมัติขั้นสุดท้าย" : "ตรวจสอบและลงนามแผน"}</h3><p>${escapeHtml(p.teacher_name || "ครูผู้สอน")} · ${escapeHtml(p.subject_name)}</p></div><button class="modal-close">×</button></div>
    <div class="form-grid">
      <div class="field"><label>การดำเนินการ</label><select class="select" id="review-decision"><option value="approve">อนุมัติ</option><option value="revision">ส่งกลับแก้ไข</option><option value="reject">ไม่อนุมัติ</option></select></div>
      <div class="field" id="review-signature-field"><label>ลายเซ็นของ${reviewerTitle}</label><select class="select" id="review-signature"><option value="">เลือกลายเซ็น</option>${state.signatures.map(s => `<option value="${s.id}" ${s.id===preferredSignatureId ? 'selected' : ''}>${escapeHtml(s.label || 'ลายเซ็น')} · ${s.source === 'drawn' ? 'เซ็นสด' : 'รูปภาพ'} ${s.id===preferredSignatureId ? '• ใช้อัตโนมัติ/ค่าเริ่มต้น' : ''}</option>`).join('')}</select><div class="signature-help"><span>การอนุมัติต้องมีลายเซ็น</span><button type="button" class="link-button" id="review-manage-signature">สร้าง/จัดการลายเซ็น</button></div></div>
      <div class="field"><label>ความคิดเห็น / หมายเหตุ</label><textarea class="input textarea" id="review-comment" placeholder="จำเป็นเมื่อส่งกลับแก้ไขหรือไม่อนุมัติ"></textarea></div>
    </div><div class="modal-actions"><button class="btn btn-ghost modal-cancel">ยกเลิก</button><button class="btn btn-primary" id="review-confirm">ยืนยัน</button></div></div>`;
  document.body.appendChild(modal);
  const close = () => modal.remove();
  modal.querySelector(".modal-close").addEventListener("click", close);
  modal.querySelector(".modal-cancel").addEventListener("click", close);
  modal.querySelector("#review-manage-signature").addEventListener("click", () => { close(); signatureManagerModal(); });
  const decision = modal.querySelector("#review-decision");
  const sigField = modal.querySelector("#review-signature-field");
  decision.addEventListener("change", () => sigField.classList.toggle("hidden", decision.value !== "approve"));
  modal.querySelector("#review-confirm").addEventListener("click", async e => {
    const d = decision.value;
    const comment = modal.querySelector("#review-comment").value.trim();
    if (["revision","reject"].includes(d) && !comment) return toast("กรุณาระบุเหตุผล", "ต้องมีความคิดเห็นเมื่อส่งกลับหรือไม่อนุมัติ", "error");
    const signatureId = d === "approve" ? (modal.querySelector("#review-signature").value || null) : null;
    if (d === "approve" && !signatureId) return toast("กรุณาเลือกลายเซ็น", `${reviewerTitle}ต้องลงนามก่อนอนุมัติ`, "error");

    buttonLoading(e.currentTarget, true, "กำลังบันทึก...");
    const rpc = director ? "director_review_lesson_plan" : "head_review_lesson_plan";
    const args = { p_lesson_plan_id: p.id, p_decision: d, p_comment: comment || null, p_signature_id: signatureId };
    const { error } = await supabase.rpc(rpc, args);
    buttonLoading(e.currentTarget, false);
    if (error) return toast("ดำเนินการไม่สำเร็จ", error.message, "error");
    close();

    if (director && d === "approve") {
      toast("อนุมัติขั้นสุดท้ายแล้ว", "กำลังสร้าง PDF ฉบับอนุมัติถาวร...", "success");
      await loadLessonPlanWorkspace();
      try {
        await generateAndArchiveApprovedPdf({ silent: true });
        toast("สร้าง Approved PDF แล้ว", "ครูและผู้เกี่ยวข้องสามารถดาวน์โหลดฉบับเดิมได้ตลอดตามสิทธิ์", "success");
      } catch (pdfError) {
        console.error("Approved PDF generation failed", pdfError);
        toast("อนุมัติสำเร็จ แต่สร้าง PDF ยังไม่สำเร็จ", "เปิดแผนนี้แล้วกด “สร้าง Approved PDF” เพื่อสร้างใหม่ได้", "error");
      }
      await renderDashboard();
      return;
    }

    toast("บันทึกผลการตรวจแล้ว", d === "approve" ? (approvalIsParallel("lesson_plans")?"บันทึกช่องรับรองแล้ว · เอกสารจะสมบูรณ์เมื่อทุกช่องครบ":"ลงนามแล้วและ Workflow เดินหน้าสู่ขั้นตอนถัดไป") : "ครูผู้ส่งได้รับการแจ้งเตือนแล้ว", "success");
    await renderDashboard();
  });
}

function signatureManagerModal(initialMode="drawn") {
  const roleLabel = state.profile.role === "department_head" ? "หัวหน้ากลุ่มงาน" : state.profile.role === "director" ? "ผู้บริหาร" : "ผู้ใช้งาน";
  const modal = document.createElement("div");
  modal.className = "modal-backdrop";
  modal.dataset.sigMode = initialMode==="upload"?"upload":"drawn";
  modal.innerHTML = `<div class="modal modal-signature"><div class="modal-head"><div><h3>ลายเซ็นของฉัน</h3><p>${roleLabel}สามารถเซ็นสดบนจอ หรืออัปโหลดรูปภาพลายเซ็นได้</p></div><button class="modal-close">×</button></div>
    <div class="signature-list">${state.signatures.length ? state.signatures.map(s => `<div class="signature-row"><div><strong>${escapeHtml(s.label || "ลายเซ็น")}</strong><span>${s.source === 'drawn' ? '✍ เซ็นสด' : '🖼 รูปภาพ'} · ${s.is_default ? "ค่าเริ่มต้น" : formatDate(s.created_at)}</span></div><div class="admin-actions"><button class="btn btn-ghost signature-preview" data-sig-id="${s.id}">ดู</button>${!s.is_default ? `<button class="btn btn-secondary signature-default" data-sig-id="${s.id}">ตั้งเป็นค่าเริ่มต้น</button>` : `<span class="pill active">Default</span>`}<button class="btn btn-danger signature-delete" data-sig-id="${s.id}">ลบ</button></div></div>`).join("") : `<div class="empty"><strong>ยังไม่มีลายเซ็น</strong><span>สร้างได้ทั้งแบบเซ็นสดและอัปโหลดรูปภาพ</span></div>`}</div>
    <hr class="soft-rule">
    <div class="signature-mode-tabs"><button type="button" class="signature-mode ${modal.dataset.sigMode==="drawn"?"active":""}" data-signature-mode="drawn">✍ เซ็นสด</button><button type="button" class="signature-mode ${modal.dataset.sigMode==="upload"?"active":""}" data-signature-mode="upload">🖼 อัปโหลดรูปภาพ</button></div>
    <div class="form-grid">
      <div class="field"><label>ชื่อลายเซ็น</label><input class="input" id="signature-label" placeholder="เช่น ลายเซ็น${roleLabel}"></div>
      <div id="signature-drawn-pane" class="signature-pane ${modal.dataset.sigMode==="upload"?"hidden":""}"><div class="signature-canvas-wrap"><canvas id="signature-canvas" width="900" height="300"></canvas></div><div class="signature-canvas-actions"><span>ใช้เมาส์ นิ้ว หรือปากกาเซ็นในช่องด้านบน</span><button type="button" class="btn btn-ghost" id="signature-clear">ล้างลายเซ็น</button></div></div>
      <div id="signature-upload-pane" class="signature-pane ${modal.dataset.sigMode==="upload"?"":"hidden"}"><div class="field"><label>ไฟล์ลายเซ็น</label><input class="input" id="signature-file" type="file" accept="image/png,image/jpeg,image/webp"><span class="helper">PNG, JPG หรือ WebP ไม่เกิน 5 MB · <strong>แนะนำ PNG/WebP พื้นหลังโปร่งใส</strong> เพื่อให้ลายเซ็นกลืนกับเอกสารและไม่เกิดกรอบสีขาว</span></div></div>
      <label class="check-row"><input type="checkbox" id="signature-default" ${state.signatures.length ? '' : 'checked'}> ตั้งเป็นลายเซ็นเริ่มต้น</label>
    </div>
    <div class="modal-actions"><button class="btn btn-ghost modal-cancel">ปิด</button><button class="btn btn-primary" id="signature-save">บันทึกลายเซ็น</button></div></div>`;
  document.body.appendChild(modal);
  const close = () => modal.remove();
  modal.querySelector(".modal-close").addEventListener("click", close);
  modal.querySelector(".modal-cancel").addEventListener("click", close);

  setupSignatureCanvas(modal);
  modal.querySelectorAll("[data-signature-mode]").forEach(btn => btn.addEventListener("click", () => {
    modal.dataset.sigMode = btn.dataset.signatureMode;
    modal.querySelectorAll("[data-signature-mode]").forEach(x => x.classList.toggle("active", x === btn));
    modal.querySelector("#signature-drawn-pane").classList.toggle("hidden", modal.dataset.sigMode !== "drawn");
    modal.querySelector("#signature-upload-pane").classList.toggle("hidden", modal.dataset.sigMode !== "upload");
  }));
  modal.querySelector("#signature-save").addEventListener("click", e => saveSignatureFromManager(modal, e.currentTarget));
  modal.querySelectorAll(".signature-preview").forEach(b => b.addEventListener("click", () => previewSignature(b.dataset.sigId)));
  modal.querySelectorAll(".signature-default").forEach(b => b.addEventListener("click", () => setDefaultSignature(b.dataset.sigId, modal)));
  modal.querySelectorAll(".signature-delete").forEach(b => b.addEventListener("click", () => deleteSignature(b.dataset.sigId, modal)));
}

function setupSignatureCanvas(modal) {
  const canvas = modal.querySelector("#signature-canvas");
  const ctx = canvas.getContext("2d");
  ctx.lineWidth = 5;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#0f172a";
  let drawing = false;
  let hasInk = false;

  const point = (event) => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * (canvas.width / rect.width),
      y: (event.clientY - rect.top) * (canvas.height / rect.height),
    };
  };
  canvas.addEventListener("pointerdown", e => {
    drawing = true; hasInk = true; canvas.setPointerCapture(e.pointerId);
    const p = point(e); ctx.beginPath(); ctx.moveTo(p.x, p.y);
  });
  canvas.addEventListener("pointermove", e => {
    if (!drawing) return;
    const p = point(e); ctx.lineTo(p.x, p.y); ctx.stroke();
  });
  const stop = () => { drawing = false; };
  canvas.addEventListener("pointerup", stop);
  canvas.addEventListener("pointercancel", stop);
  canvas.addEventListener("pointerleave", stop);
  modal.querySelector("#signature-clear").addEventListener("click", () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height); hasInk = false;
  });
  modal._signatureHasInk = () => hasInk;
}

function canvasBlob(canvas) {
  return new Promise(resolve => canvas.toBlob(resolve, "image/png", 1));
}

async function saveSignatureFromManager(modal, button) {
  const label = modal.querySelector("#signature-label").value.trim() || "ลายเซ็น";
  const makeDefault = modal.querySelector("#signature-default").checked;
  const mode = modal.dataset.sigMode || "drawn";
  let blob, ext, mime, source;

  if (mode === "drawn") {
    if (!modal._signatureHasInk?.()) return toast("ยังไม่มีลายเซ็น", "กรุณาเซ็นในช่องก่อนบันทึก", "error");
    blob = await canvasBlob(modal.querySelector("#signature-canvas"));
    ext = "png"; mime = "image/png"; source = "drawn";
  } else {
    const file = modal.querySelector("#signature-file").files[0];
    if (!file) return toast("กรุณาเลือกไฟล์", "เลือกรูปภาพลายเซ็นก่อนบันทึก", "error");
    if (!["image/png","image/jpeg","image/webp"].includes(file.type)) return toast("ประเภทไฟล์ไม่รองรับ", "ใช้ PNG, JPG หรือ WebP", "error");
    if (file.size > 5 * 1024 * 1024) return toast("ไฟล์ใหญ่เกินไป", "ลายเซ็นต้องไม่เกิน 5 MB", "error");
    blob = file;
    ext = file.type === "image/png" ? "png" : file.type === "image/webp" ? "webp" : "jpg";
    mime = file.type; source = "upload";
  }

  buttonLoading(button, true, "กำลังบันทึก...");
  if (makeDefault && state.signatures.length) {
    const { error: clearError } = await supabase.from("signatures").update({ is_default: false }).eq("user_id", state.user.id);
    if (clearError) { buttonLoading(button, false); return toast("บันทึกไม่สำเร็จ", clearError.message, "error"); }
  }

  const path = `${state.user.id}/${crypto.randomUUID()}.${ext}`;
  const { error: upErr } = await supabase.storage.from("signatures").upload(path, blob, { contentType: mime, upsert: false });
  if (upErr) { buttonLoading(button, false); return toast("อัปโหลดไม่สำเร็จ", upErr.message, "error"); }

  const { error } = await supabase.from("signatures").insert({
    user_id: state.user.id,
    label,
    bucket_id: "signatures",
    storage_path: path,
    is_default: makeDefault || state.signatures.length === 0,
    source,
  });
  if (error) {
    await supabase.storage.from("signatures").remove([path]);
    buttonLoading(button, false);
    return toast("บันทึกลายเซ็นไม่สำเร็จ", error.message, "error");
  }

  buttonLoading(button, false);
  modal.remove();
  toast("เพิ่มลายเซ็นแล้ว", source === "drawn" ? "บันทึกลายเซ็นสดเรียบร้อย" : "บันทึกรูปภาพลายเซ็นเรียบร้อย", "success");
  await refreshMySignatureProfile();
  await renderDashboard();
  signatureManagerModal(mode);
}

async function previewSignature(id) {
  const sig = state.signatures.find(s => s.id === id) || state.lessonDetail?.signatures?.find(s => s.id === id);
  if (!sig) return;
  const { data, error } = await supabase.storage.from(sig.bucket_id || "signatures").download(sig.storage_path);
  if (error) return toast("เปิดลายเซ็นไม่สำเร็จ", error.message, "error");
  const url = URL.createObjectURL(data); window.open(url, "_blank", "noopener,noreferrer"); setTimeout(() => URL.revokeObjectURL(url), 60000);
}

async function setDefaultSignature(id, modal) {
  await supabase.from("signatures").update({ is_default: false }).eq("user_id", state.user.id);
  const { error } = await supabase.from("signatures").update({ is_default: true }).eq("id", id);
  if (error) return toast("อัปเดตไม่สำเร็จ", error.message, "error");
  modal.remove(); await refreshMySignatureProfile(); await renderDashboard(); signatureManagerModal();
}

async function deleteSignature(id, modal) {
  const sig = state.signatures.find(s => s.id === id); if (!sig) return;
  if (!window.confirm("ลบลายเซ็นนี้หรือไม่? ลายเซ็นที่ถูกใช้กับเอกสารหรือ Snapshot แล้วจะลบไม่ได้")) return;
  const { error } = await supabase.from("signatures").delete().eq("id", id);
  if (error) return toast("ลบไม่ได้", error.message || "ลายเซ็นนี้อาจถูกใช้งานในเอกสารแล้ว", "error");
  const { error: storageError } = await supabase.storage.from(sig.bucket_id || "signatures").remove([sig.storage_path]);
  if (storageError) console.warn("signature storage cleanup failed", storageError);
  modal.remove(); toast("ลบลายเซ็นแล้ว", "", "success"); await refreshMySignatureProfile(); await renderDashboard(); signatureManagerModal();
}


function thaiDateOnly(value) {
  if (!value) return "—";
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(value)) ? new Date(`${value}T00:00:00`) : new Date(value);
  return new Intl.DateTimeFormat("th-TH", { day: "numeric", month: "long", year: "numeric" }).format(date);
}

function thaiDateTimeDocument(value) {
  if (!value) return "—";
  return new Intl.DateTimeFormat("th-TH", {
    day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit"
  }).format(new Date(value));
}

function actionForRole(detail, role) {
  const action = role === "department_head" ? "approve_head" : "approve_director";
  return [...(detail.timeline || [])].reverse().find(item => item.action === action) || null;
}

function signatureForAction(detail, action) {
  if (!action?.signature_id) return null;
  return (detail.signatures || []).find(sig => sig.id === action.signature_id) || null;
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

async function signatureDataUrl(signature) {
  if (!signature) return null;
  const { data, error } = await supabase.storage.from(signature.bucket_id || "signatures").download(signature.storage_path);
  if (error) {
    console.warn("Signature download failed for print", error);
    return null;
  }
  return blobToDataUrl(data);
}

async function schoolLogoDataUrl() {
  try {
    const response = await fetch("./school-logo.png", { cache: "force-cache" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return await blobToDataUrl(await response.blob());
  } catch (error) {
    console.warn("School logo could not be loaded for A4 document", error);
    return null;
  }
}

